import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {connect,newPage,evaluate,sleep,waitFor} from '../../../scripts/browser/cdp_session.mjs';
const base='https://develata.me/RSS-Reader';
const snapshot=JSON.parse(await readFile('target/handoff/release-v0.2.0/pages/12499611016/snapshot.json'));
const expected=JSON.parse(await readFile('target/handoff/release-v0.2.0/pages/expected-files.json'));
const assets=expected.filter(f=>f.path.startsWith('assets/')).map(f=>`${base}/${f.path}`);
const entries=snapshot.feeds.flatMap(f=>f.feed.entries),failures=[],network=[],responses=[],articles=[];
const client=connect((await newPage()).webSocketDebuggerUrl);
client.on('Runtime.exceptionThrown',e=>failures.push(e));
client.on('Runtime.consoleAPICalled',e=>{if(e.type==='error')failures.push(e);});
client.on('Network.responseReceived',e=>{
 responses.push({url:e.response.url,status:e.response.status,type:e.type,protocol:e.response.protocol,fromDiskCache:e.response.fromDiskCache});
 if(e.response.status>=400&&e.type!=='Image'&&!e.response.url.endsWith('/favicon.ico')&&!(e.type==='Document'&&e.response.status===404&&e.response.url.startsWith(`${base}/entries/`)))failures.push(responses.at(-1));
});
client.on('Network.requestWillBeSent',e=>{
 if(/^https?:/.test(e.request.url)&&new URL(e.request.url).origin!==new URL(base).origin&&e.type!=='Image')network.push(e.request.url);
 if(['Fetch','XHR'].includes(e.type)&&e.request.url.startsWith(base)&&!assets.includes(e.request.url))network.push(e.request.url);
});
try{
 await client.send('Runtime.enable');await client.send('Network.enable');await client.send('Page.enable');
 await client.send('Network.setCacheDisabled',{cacheDisabled:true});
 await client.send('Emulation.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});
 for(const index of [5,0]){
  const entry=entries[index];const navigation=await client.send('Page.navigate',{url:`${base}/entries/${index+1}?final-7cb83b2=1`});assert.ok(!navigation.errorText);
  await waitFor(client,`!!document.querySelector('[data-slot="reader-body-html"]')`,180000);
  const readyMs=await evaluate(client,'performance.now()');
  assert.deepEqual(failures,[]);
  await waitFor(client,`[...document.querySelectorAll('[data-slot="reader-body-html"] img.latex')].every(img=>img.complete)`,60000);
  const rendering=await evaluate(client,`({
    title:document.querySelector('[data-slot="reader-title"]').textContent,
    original:document.querySelector('[data-action="open-original"]').href,
    bodyLength:document.querySelector('[data-slot="reader-body-html"]').textContent.trim().length,
    math:[...document.querySelectorAll('[data-slot="reader-body-html"] math')].map(m=>({namespace:m.namespaceURI,width:m.getBoundingClientRect().width,height:m.getBoundingClientRect().height})),
    images:[...document.querySelectorAll('[data-slot="reader-body-html"] img.latex')].map(i=>({src:i.currentSrc||i.src,complete:i.complete,naturalWidth:i.naturalWidth,width:i.getBoundingClientRect().width})),
    resources:performance.getEntriesByType('resource').filter(r=>r.name.includes('/assets/')).map(r=>({name:r.name,duration:r.duration,encodedBodySize:r.encodedBodySize}))
  })`);
  assert.equal(rendering.title,entry.title);assert.equal(rendering.original,entry.url);assert.ok(rendering.bodyLength>100);
  assert.equal(rendering.math.length,(entry.content_html.match(/<math(?:\s|\/?>)/g)??[]).length);
  assert.ok(rendering.math.every(m=>m.namespace==='http://www.w3.org/1998/Math/MathML'&&m.width>0&&m.height>0));
  assert.equal(rendering.images.length,(entry.content_html.match(/class="latex"/g)??[]).length);
  assert.ok(rendering.images.every(i=>i.complete&&i.naturalWidth>0&&i.width>0));
  assert.deepEqual(rendering.resources.map(r=>r.name).sort(),[...assets].sort());
  const clip=await evaluate(client,`(()=>{const b=document.querySelector('[data-slot="reader-body-html"]');const m=b.querySelector('mlabeledtr')?.closest('math')??b.querySelector('img.latex')??b;const r=m.getBoundingClientRect();const y=Math.max(0,Math.floor(r.top+scrollY-Math.max(0,(innerHeight-r.height)/2)));return{x:0,y,width:document.documentElement.clientWidth,height:Math.min(innerHeight,document.documentElement.scrollHeight-y),scale:1};})()`);
  const shot=await client.send('Page.captureScreenshot',{clip,captureBeyondViewport:true});
  await writeFile(`target/handoff/release-v0.2.0/pages/article-${index+1}-formula.png`,Buffer.from(shot.data,'base64'));
  articles.push({index:index+1,readyMs,...rendering});console.log(JSON.stringify({article:index+1,readyMs,math:rendering.math.length,formulaImages:rendering.images.length,status:'pass'}));
 }
 assert.deepEqual(failures,[]);assert.deepEqual(network,[]);
 const record={status:'pass',scope:'Targeted confirmation of final deployed bundle: both formula formats, real titles/body/original links, correct new assets. Full interaction suite passed on identical product sources in deployment 699dcf6; this is not a second full suite.',sourceSha:'52b5e9fc9de57767cd0e533ce9d826949139ffb8',pagesRun:39948302751,checkedAt:new Date().toISOString(),browser:await evaluate(client,'navigator.userAgent'),probeSha256:createHash('sha256').update(await readFile(new URL(import.meta.url))).digest('hex'),fetchedAt:snapshot.fetched_at,articles,responses,failures,network};
 await writeFile('target/handoff/release-v0.2.0/pages/reader-check.json',JSON.stringify(record,null,2)+'\n');
}catch(error){await writeFile('target/handoff/release-v0.2.0/pages/reader-failure.json',JSON.stringify({error:String(error),failures,network,responses,articles},null,2));throw error;}
finally{await client.send('Page.close').catch(()=>{});client.close();}
